<?php
require_once __DIR__.'/global.php';
$page=(string)($_GET['page']??'home');
$allowed=['home','menu','product','cart','add_cart','checkout','order','login','register','logout','account','contact'];
if(!in_array($page,$allowed,true)){$page='home';http_response_code(404);}
$notice=flash();$formError='';$dbError='';
function site_categories(mysqli $conn): array {$r=$conn->query('SELECT * FROM categories WHERE is_active=1 ORDER BY sort_order,id');return $r->fetch_all(MYSQLI_ASSOC);}
function cart_rows(mysqli $conn): array {$rows=[];$cart=$_SESSION['cart']??[];foreach($cart as $id=>$qty){$id=(int)$id;$q=$conn->prepare('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.is_active=1 AND c.is_active=1');$q->bind_param('i',$id);$q->execute();$p=$q->get_result()->fetch_assoc();$q->close();if($p){$p['quantity']=(int)$qty;$p['line_total']=(float)$p['price']*$p['quantity'];$rows[]=$p;}else unset($_SESSION['cart'][$id]);}return $rows;}
function render_header(string $title): void {global $notice; $u=user();$count=array_sum($_SESSION['cart']??[]);?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#bd4d32"><title><?=h($title)?> · Bếp Mộc</title><link rel="stylesheet" href="css/bep-moc.css?v=1"></head><body><header class="site-header"><div class="nav-wrap"><a class="brand" href="index.php"><span class="brand-mark">B</span><span><strong>BẾP MỘC</strong><small>MÓN NGON MỖI NGÀY</small></span></a><nav class="nav-links"><a href="index.php">Trang chủ</a><a href="index.php?page=menu">Thực đơn</a><a href="index.php?page=home#story">Câu chuyện</a><a href="index.php?page=contact">Liên hệ</a></nav><div class="nav-actions"><a href="index.php?page=cart">Giỏ hàng <span class="cart-count"><?=$count?></span></a><?php if($u):?><a class="account-link" href="index.php?page=account"><?=h($u['fullname'])?></a><?php if($u['role']==='admin'):?><a href="admin/index.php">Quản trị</a><?php endif;?><form method="post" action="index.php?page=logout" style="display:inline"><?=csrf_field()?><button class="button button-sm" type="submit">Đăng xuất</button></form><?php else:?><a href="index.php?page=login">Đăng nhập</a><a class="button button-sm" href="index.php?page=register">Tạo tài khoản</a><?php endif;?></div></div></header><?php if($notice):?><div class="notice"><?=h($notice)?></div><?php endif;?><main class="page"><?php }
function render_footer(): void { ?><footer class="footer"><div class="footer-inner"><a class="brand footer-brand" href="index.php"><span class="brand-mark">B</span><span><strong>BẾP MỘC</strong><small>MÓN NGON MỖI NGÀY</small></span></a><p>Nấu bằng sự chỉn chu, gửi đến bạn bữa ăn ấm lành.</p><small>© <?=date('Y')?> Bếp Mộc · 08:00–21:30 mỗi ngày</small></div></footer></main></body></html><?php }
function product_card(array $p): void { ?><article class="product-card"><a class="product-image" href="index.php?page=product&id=<?=$p['id']?>"><img loading="lazy" src="<?=h(image_url($p['image_url']??''))?>" alt="<?=h($p['name'])?>"><?php if(!empty($p['is_featured'])):?><span class="product-tag">BẾP MỘC GỢI Ý</span><?php endif;?></a><div class="product-info"><div class="product-title-row"><a href="index.php?page=product&id=<?=$p['id']?>"><h3><?=h($p['name'])?></h3></a><span class="product-price"><?=money($p['price'])?></span></div><p><?=h($p['description']??'')?></p><span class="stock-note <?=$p['stock']<5?'stock-low':'stock-good'?>"><?=$p['stock']>0?($p['stock']<5?'Sắp hết món':'Còn món'):'Tạm hết món'?></span><form method="post" action="index.php?page=add_cart"><?=csrf_field()?><input type="hidden" name="id" value="<?=$p['id']?>"><button class="button button-sm full" <?=$p['stock']<1?'disabled':''?>><?=$p['stock']<1?'Tạm hết':'Thêm vào giỏ +'?></button></form></div></article><?php }
function page_hero(string $eyebrow,string $title,string $description=''): void { ?><section class="page-hero"><span class="eyebrow"><?=h($eyebrow)?></span><h1 class="page-title"><?=h($title)?></h1><?php if($description!==''):?><p class="muted"><?=h($description)?></p><?php endif;?></section><?php }
function status_label(string $status): string {return ['pending'=>'Chờ xác nhận','confirmed'=>'Đã xác nhận','preparing'=>'Đang chuẩn bị','shipping'=>'Đang giao','completed'=>'Hoàn tất','cancelled'=>'Đã hủy'][$status]??$status;}
function payment_label(string $status): string {return ['unpaid'=>'Chưa thanh toán','reported'=>'Đã báo chuyển khoản','paid'=>'Đã nhận tiền'][$status]??$status;}

// Cart mutation.
if($page==='add_cart'&&$_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$q=$conn->prepare('SELECT stock,name FROM products WHERE id=? AND is_active=1');$q->bind_param('i',$id);$q->execute();$p=$q->get_result()->fetch_assoc();$q->close();if($p&&(int)$p['stock']>(int)($_SESSION['cart'][$id]??0)){$_SESSION['cart'][$id]=($_SESSION['cart'][$id]??0)+1;flash(h($p['name']).' đã được thêm vào giỏ.');}else flash('Món đã hết hoặc số lượng trong kho không đủ.');go('index.php?page=menu');}
if($page==='cart'&&$_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(isset($_POST['remove']))unset($_SESSION['cart'][(int)$_POST['remove']]);else foreach($_POST['quantity']??[] as $id=>$qty){$id=(int)$id;$qty=(int)$qty;if($qty<1){unset($_SESSION['cart'][$id]);continue;}$q=$conn->prepare('SELECT stock FROM products WHERE id=? AND is_active=1');$q->bind_param('i',$id);$q->execute();$p=$q->get_result()->fetch_assoc();$q->close();if($p)$_SESSION['cart'][$id]=min($qty,(int)$p['stock']);else unset($_SESSION['cart'][$id]);}flash('Giỏ hàng đã được cập nhật.');go('index.php?page=cart');}

// User access.
if($page==='register'&&$_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim((string)($_POST['fullname']??''));$email=strtolower(trim((string)($_POST['email']??'')));$phone=trim((string)($_POST['phone']??''));$password=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm_password']??'');if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8||$password!==$confirm)$formError='Vui lòng kiểm tra họ tên, email và mật khẩu (tối thiểu 8 ký tự, xác nhận phải khớp).';else{$hash=password_hash($password,PASSWORD_DEFAULT);try{$q=$conn->prepare("INSERT INTO users(fullname,email,phone,password_hash,role) VALUES(?,?,?,?,'customer')");$q->bind_param('ssss',$name,$email,$phone,$hash);$q->execute();flash('Đăng ký thành công. Bạn có thể đăng nhập ngay.');go('index.php?page=login');}catch(mysqli_sql_exception $e){$formError=$e->getCode()===1062?'Email này đã được đăng ký.':'Chưa thể tạo tài khoản, vui lòng thử lại.';}}}
if($page==='login'&&$_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$q=$conn->prepare('SELECT id,fullname,email,phone,password_hash,role,gender,birth_date FROM users WHERE email=? LIMIT 1');$q->bind_param('s',$email);$q->execute();$u=$q->get_result()->fetch_assoc();$q->close();if($u&&password_verify($password,$u['password_hash'])){unset($u['password_hash']);session_regenerate_id(true);$_SESSION['user']=$u;go($u['role']==='admin'?'admin/index.php':'index.php?page=account');}$formError='Email hoặc mật khẩu chưa chính xác.';}
if($page==='logout'&&$_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$_SESSION=[];session_regenerate_id(true);flash('Bạn đã đăng xuất. Hẹn gặp lại!');go('index.php');}

// Profile and password updates.
if($page==='account'&&$_SERVER['REQUEST_METHOD']==='POST'){require_login();check_csrf();$action=(string)($_POST['action']??'');$uid=(int)user()['id'];if($action==='profile'){$name=trim((string)($_POST['fullname']??''));$phone=trim((string)($_POST['phone']??''));$gender=(string)($_POST['gender']??'');$birth=$_POST['birth_date']?:null;if(mb_strlen($name)<2||!in_array($gender,['','male','female','other'],true))$formError='Thông tin cá nhân chưa hợp lệ.';else{$q=$conn->prepare('UPDATE users SET fullname=?,phone=?,gender=NULLIF(?,\'\'),birth_date=? WHERE id=?');$q->bind_param('ssssi',$name,$phone,$gender,$birth,$uid);$q->execute();$_SESSION['user']['fullname']=$name;$_SESSION['user']['phone']=$phone;$_SESSION['user']['gender']=$gender;$_SESSION['user']['birth_date']=$birth;flash('Hồ sơ đã được cập nhật.');go('index.php?page=account');}}elseif($action==='password'){$old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');$q=$conn->prepare('SELECT password_hash FROM users WHERE id=?');$q->bind_param('i',$uid);$q->execute();$row=$q->get_result()->fetch_assoc();$q->close();if(!$row||!password_verify($old,$row['password_hash'])||strlen($new)<8)$formError='Mật khẩu cũ chưa đúng hoặc mật khẩu mới dưới 8 ký tự.';else{$hash=password_hash($new,PASSWORD_DEFAULT);$q=$conn->prepare('UPDATE users SET password_hash=? WHERE id=?');$q->bind_param('si',$hash,$uid);$q->execute();flash('Đổi mật khẩu thành công.');go('index.php?page=account');}}}

// Transactional checkout: verify stock and prices on the server.
if($page==='checkout'&&$_SERVER['REQUEST_METHOD']==='POST'){require_login();check_csrf();$name=trim((string)($_POST['customer_name']??''));$phone=trim((string)($_POST['phone']??''));$address=trim((string)($_POST['address']??''));$note=trim((string)($_POST['note']??''));$method=(string)($_POST['payment_method']??'cod');$cart=$_SESSION['cart']??[];if(!$cart)$formError='Giỏ hàng đang trống.';elseif(mb_strlen($name)<2||mb_strlen($address)<5||!in_array($method,['cod','bank_transfer'],true))$formError='Vui lòng nhập họ tên, địa chỉ và phương thức thanh toán hợp lệ.';else{$conn->begin_transaction();try{$locked=[];$total=0;$q=$conn->prepare('SELECT id,name,price,stock FROM products WHERE id=? AND is_active=1 FOR UPDATE');foreach($cart as $id=>$qty){$id=(int)$id;$qty=(int)$qty;$q->bind_param('i',$id);$q->execute();$p=$q->get_result()->fetch_assoc();if(!$p||$qty<1||(int)$p['stock']<$qty)throw new DomainException('Một món vừa hết hoặc không đủ số lượng. Hãy cập nhật giỏ hàng.');$p['quantity']=$qty;$locked[]=$p;$total+=(float)$p['price']*$qty;}$q->close();$code='BM'.strtoupper(bin2hex(random_bytes(4)));$uid=(int)user()['id'];$q=$conn->prepare("INSERT INTO orders(code,user_id,customer_name,phone,address,note,total,status,payment_method,payment_status) VALUES(?,?,?,?,?,?,?,'pending',?,'unpaid')");$q->bind_param('sissssds',$code,$uid,$name,$phone,$address,$note,$total,$method);$q->execute();$orderId=$conn->insert_id;$item=$conn->prepare('INSERT INTO order_items(order_id,product_id,product_name,price,quantity) VALUES(?,?,?,?,?)');$stock=$conn->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');foreach($locked as $p){$pid=(int)$p['id'];$pname=$p['name'];$price=(float)$p['price'];$qty=(int)$p['quantity'];$item->bind_param('iisdi',$orderId,$pid,$pname,$price,$qty);$item->execute();$stock->bind_param('iii',$qty,$pid,$qty);$stock->execute();if($stock->affected_rows!==1)throw new DomainException('Tồn kho vừa thay đổi. Vui lòng đặt lại.');}$conn->commit();unset($_SESSION['cart']);flash('Đơn hàng '.$code.' đã được tạo.');go('index.php?page=order&id='.$orderId);}catch(Throwable $e){$conn->rollback();$formError=$e instanceof DomainException?$e->getMessage():'Chưa thể tạo đơn hàng, vui lòng thử lại.';}}}

// Report bank transfer after the customer has made the transfer.
if($page==='order'&&$_SERVER['REQUEST_METHOD']==='POST'){require_login();check_csrf();$id=(int)($_POST['id']??0);$uid=(int)user()['id'];$q=$conn->prepare("UPDATE orders SET payment_status='reported',payment_reported_at=NOW() WHERE id=? AND user_id=? AND payment_method='bank_transfer' AND payment_status='unpaid'");$q->bind_param('ii',$id,$uid);$q->execute();$changed=$q->affected_rows;$q->close();flash($changed?'Đã báo chuyển khoản. Bếp Mộc sẽ kiểm tra giao dịch.':'Đơn hàng đã được cập nhật.');go('index.php?page=order&id='.$id);}
if($page==='contact'&&$_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$message=trim((string)($_POST['message']??''));if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($message)<5)$formError='Vui lòng nhập đầy đủ thông tin.';else{$q=$conn->prepare('INSERT INTO feedback(name,email,message) VALUES(?,?,?)');$q->bind_param('sss',$name,$email,$message);$q->execute();flash('Cảm ơn bạn đã gửi lời nhắn cho Bếp Mộc.');go('index.php?page=contact');}}

if($page==='home'){render_header('Bữa cơm nhà, vị ngon mỗi ngày');$r=$conn->query('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.is_active=1 AND c.is_active=1 ORDER BY p.is_featured DESC,p.id LIMIT 8');$featured=$r->fetch_all(MYSQLI_ASSOC);?><section class="hero"><div class="hero-copy"><span class="eyebrow">BẾP MỘC · NẤU MỖI NGÀY</span><h1>Bữa cơm nhà,<br><em>vị ngon thân quen.</em></h1><p>Món Việt nấu nóng mỗi ngày, nguyên liệu chọn kỹ, giao đến bạn thật nhanh. Chọn món ngon cho bữa ăn hôm nay nhé.</p><a class="button" href="index.php?page=menu">Khám phá thực đơn <span>↗</span></a><p class="muted" style="margin-top:24px">✦ Nấu mới theo đơn · Giao tận nơi · Thanh toán tiện lợi</p></div><div class="hero-image"><img src="https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=1200&q=88" alt="Mâm cơm Việt tươi ngon"></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">MÓN ĐƯỢC YÊU THÍCH</span><h2>Hôm nay ăn gì?</h2><p>Món ngon nổi bật từ căn bếp của chúng tôi.</p></div><a class="text-link" href="index.php?page=menu">Xem toàn bộ thực đơn ↗</a></div><div class="product-grid"><?php foreach($featured as $p)product_card($p);?></div></section><section class="section" id="story"><div class="hero-split"><div class="hero-note"><span class="eyebrow">CÂU CHUYỆN BẾP MỘC</span><h2 class="content-heading">Nấu chỉn chu như bữa cơm nhà.</h2><p>Mỗi món được chuẩn bị từ nguyên liệu tươi trong ngày, nêm nếm vừa vị và đóng gói cẩn thận để bữa ăn của bạn luôn ấm ngon.</p></div><div class="hero-note"><span class="eyebrow">GIỜ MỞ CỬA</span><h2 class="content-heading">08:00 – 21:30</h2><p>Nhận món mỗi ngày. Giao hàng miễn phí cho đơn từ 150.000₫ trong khu vực quán.</p></div></div></section><?php render_footer();exit;}
if($page==='menu'){render_header('Thực đơn Bếp Mộc');$cats=site_categories($conn);$cat=(int)($_GET['cat']??0);$search=trim((string)($_GET['q']??''));$sort=(string)($_GET['sort']??'popular');$sortSql=['popular'=>'p.is_featured DESC,p.id DESC','newest'=>'p.id DESC','price_low'=>'p.price ASC','price_high'=>'p.price DESC'][$sort]??'p.is_featured DESC,p.id DESC';$where='p.is_active=1 AND c.is_active=1';if($cat>0)$where.=' AND p.category_id='.(int)$cat;if($search!==''){$safe=$conn->real_escape_string($search);$where.=" AND (p.name LIKE '%$safe%' OR p.description LIKE '%$safe%')";}$r=$conn->query("SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE $where ORDER BY $sortSql");$products=$r->fetch_all(MYSQLI_ASSOC);?><section class="menu-hero"><span class="eyebrow">MÓN NGON MỖI NGÀY</span><h1 class="page-title">Thực đơn Bếp Mộc</h1><p>Món Việt thân quen, chuẩn bị mới trong ngày.</p></section><form class="toolbar" method="get"><input type="hidden" name="page" value="menu"><input type="search" name="q" value="<?=h($search)?>" placeholder="Tìm cơm, bún, món ăn nhẹ..."><select name="sort"><option value="popular" <?=$sort==='popular'?'selected':''?>>Gợi ý</option><option value="newest" <?=$sort==='newest'?'selected':''?>>Mới nhất</option><option value="price_low" <?=$sort==='price_low'?'selected':''?>>Giá thấp đến cao</option><option value="price_high" <?=$sort==='price_high'?'selected':''?>>Giá cao đến thấp</option></select><button class="button">Tìm món</button></form><nav class="category-chips"><a class="chip <?=$cat===0?'active':''?>" href="index.php?page=menu">Tất cả món</a><?php foreach($cats as $c):?><a class="chip <?=$cat===(int)$c['id']?'active':''?>" href="index.php?page=menu&cat=<?=$c['id']?>"><?=h($c['name'])?></a><?php endforeach;?></nav><section class="menu-layout"><div class="section-head"><div><span class="eyebrow">BẾP ĐANG LÊN MÓN</span><h2><?=$cat?'Món theo danh mục':'Món ngon hôm nay'?></h2><p><?=count($products)?> món<?= $search!==''?' phù hợp với “'.h($search).'”':''?></p></div></div><?php if($products):?><div class="product-grid"><?php foreach($products as $p)product_card($p);?></div><?php else:?><div class="no-results">Chưa tìm thấy món phù hợp. <a class="text-link" href="index.php?page=menu">Xem tất cả món</a></div><?php endif;?></section><?php render_footer();exit;}
if($page==='product'){$id=(int)($_GET['id']??0);$q=$conn->prepare('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.is_active=1');$q->bind_param('i',$id);$q->execute();$p=$q->get_result()->fetch_assoc();$q->close();if(!$p)go('index.php?page=menu');render_header($p['name']);?><section class="product-detail"><img src="<?=h(image_url($p['image_url']))?>" alt="<?=h($p['name'])?>"><div><span class="eyebrow"><?=h($p['category_name'])?> · BẾP MỘC</span><h1><?=h($p['name'])?></h1><p><?=h($p['description'])?></p><p class="product-price"><?=money($p['price'])?></p><p class="stock-note <?=$p['stock']<5?'stock-low':'stock-good'?>">Còn <?=number_format((int)$p['stock'])?> phần</p><form method="post" action="index.php?page=add_cart"><?=csrf_field()?><input type="hidden" name="id" value="<?=$p['id']?>"><button class="button" <?=$p['stock']<1?'disabled':''?>>Thêm món vào giỏ</button></form></div></section><?php render_footer();exit;}
if($page==='cart'){render_header('Giỏ hàng');$rows=cart_rows($conn);$total=array_sum(array_column($rows,'line_total'));?><section class="page-hero"><span class="eyebrow">GIỎ HÀNG</span><h1 class="page-title">Món ngon bạn chọn</h1></section><?php if(!$rows):?><div class="empty-state"><h2>Giỏ hàng đang trống</h2><p>Chọn món ngon cho bữa ăn hôm nay nhé.</p><a class="button" href="index.php?page=menu">Xem thực đơn</a></div><?php else:?><form method="post" class="cart-layout"><?=csrf_field()?><div><?php foreach($rows as $p):?><div class="cart-row"><img src="<?=h(image_url($p['image_url']))?>" alt=""><div><h3><?=h($p['name'])?></h3><small><?=money($p['price'])?> · còn <?=$p['stock']?> phần</small></div><input class="quantity" type="number" min="0" max="<?=$p['stock']?>" name="quantity[<?=$p['id']?>]" value="<?=$p['quantity']?>"><strong><?=money($p['line_total'])?></strong><button class="remove" type="submit" name="remove" value="<?=$p['id']?>" title="Xóa món">×</button></div><?php endforeach;?><button class="button button-outline cart-update">Cập nhật giỏ hàng</button></div><aside class="summary"><h2>Tóm tắt đơn hàng</h2><div class="summary-row"><span>Tạm tính</span><b><?=money($total)?></b></div><div class="summary-row"><span>Giao hàng</span><b>Miễn phí</b></div><div class="summary-row summary-total"><span>Tổng cộng</span><b><?=money($total)?></b></div><a class="button full" href="index.php?page=checkout">Tiến hành đặt hàng</a></aside></form><?php endif;?><?php render_footer();exit;}
